mapper.select:
SELECT A.PROJ_ID AS projId , A.PROJ_NM AS projNm , A.PROJ_TYPE AS projType , A.STATUS AS status , A.START_DT AS startDt , A.END_DT AS endDt , B.CONT_NM AS contNm , C.USER_NM AS mainMgrNm FROM TB_PROJECT A LEFT OUTER JOIN TB_CONTRACT B ON A.CONT_ID = B.CONT_ID LEFT OUTER JOIN COMVNUSERMASTER C ON A.M_EMP_ID = C.ESNTL_ID WHERE A.DEL_YN = 'N'
AND A.PROJ_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.PROJ_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
INSERT INTO TB_PROJECT (
    PROJ_NM, PROJ_TYPE, STATUS, START_DT, END_DT
) VALUES (
    #{projNm}, #{projType}, #{status}, NULLIF(#{startDt},''), NULLIF(#{endDt},'')
)

mapper.update:
UPDATE TB_PROJECT SET
      PROJ_NM = #{projNm}
    , PROJ_TYPE = #{projType}
    , STATUS = #{status}
    , START_DT = NULLIF(#{startDt},'')
    , END_DT = NULLIF(#{endDt},'')
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE PROJ_ID = #{projId}

UPDATE TB_PROJECT SET 
      DEL_YN = 'Y'
    , LAST_UPDUSR_ID = #{lastUpdusrId}
WHERE PROJ_ID = #{projId}

UPDATE TB_PROJECT
   SET STATUS = #{status}

     , LAST_UPDUSR_ID = #{lastUpdusrId}

 WHERE PROJ_ID = #{selectedId}

UPDATE TB_ASSIGNMENT 
   SET DEL_YN = 'Y',
       LAST_UPDUSR_ID = #{lastUpdusrId}
 WHERE ASSIGN_ID = #{assignId}
